        if(image[sr][sc] != initColor) return;

        image[sr][sc] = newColor;

        // 4 directions 
        DFS(image, sr + 1, sc, newColor, initColor);
        DFS(image, sr, sc + 1, newColor, initColor);
        DFS(image, sr - 1, sc, newColor, initColor);
        DFS(image, sr, sc - 1, newColor, initColor);

    }
}
