## Solution
```java[]
class Solution {
    // DelRow and delCol for neighbors
    private int[] delRow = {-1, 0, 1, 0};
    private int[] delCol = {0, 1, 0, -1};
  public int[][] floodFill(int[][] image, int sr, int sc, int newColor) {
    int n = image.length;
    int m = image[0].length;

    boolean[][] vis = new boolean[n][m];

    bfs(image, sr, sc, newColor, vis);
    return image;
  }

  private boolean isValid(int row, int col, int n, int m) {
    if ((row>=0 && row<n) && (col>=0 && col<m)) {
        return true;
    }
    return false;
  }

  private void bfs (int[][] image, int row, int col, int newColor, boolean[][] vis){
    vis[row][col] = true;
    int currColor = image[row][col];

    Queue<int[]> q = new LinkedList();
    q.add(new int[]{row, col});
    image[row][col] = newColor;
    int n = image.length;
    int m = image[0].length;

    while (!q.isEmpty()){
        int[] cell = q.poll();
        int currRow = cell[0];
        int currCol = cell[1];

        for(int i=0;i<4;i++){
            int nRow = currRow+delRow[i];
            int nCol = currCol+delCol[i];
            if (isValid(nRow, nCol, n, m) && !vis[nRow][nCol] && image[nRow][nCol] == currColor){
                vis[nRow][nCol] = true;
                image[nRow][nCol] = newColor;
                q.add(new int[]{nRow, nCol});
            }
        }
    }
  }
}

```

